    ins={(r,c) for y,x,yy,xx,k in frames for r in range(y,yy+1) for c in range(x,xx+1)}
    counts={}
    for r in range(R):
      for c in range(C):
        if g[r][c] and (r,c) not in ins: counts.setdefault(g[r][c],[]).append((r,c))
    # Determine which marker colors are meaningful from repeated locally structured groups.
    # The marker color with smallest multiplicity is the motif color.
    motif=min(counts,key=lambda k:len(counts[k])) if counts else 0
    for y,x,yy,xx,k in frames:
